import org.jsoup.safety.Safelist;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;

public class SafelistTest {

    @Test
    public void none_emptySetTest() {
        Set<String> set = new HashSet<>();
        Safelist safeList = Safelist.none();
        assertTrue(safeList.addTags(set).isEmpty());
    }

    @Test
    public void simpleText_noCharsAddedTest() {
        Set<String> set = new HashSet<>();
        Safelist safeList = Safelist.simpleText();
        assertFalse(safeList.addTags(set).containsAny(set));
    }

    @Test
    public void basic_emptySetTest() {
        Set<String> set = new HashSet<>();
        Safelist safeList = Safelist.basic();
        assertTrue(safeList.removeTags(set).isEmpty());
    }

    @Test
    public void relaxed_addCharsReturnsTrueTest() {
        Set<String> set = new HashSet<>(Arrays.asList("img", "a"));
        Safelist safeList = Safelist.relaxed();
        assertTrue(safeList.addTags(set));
    }

    @Test
    public void basic_removeCharsReturnsFalseTest() {
        Set<String> set = new HashSet<>(Arrays.asList("img", "a"));
        Safelist safeList = Safelist.basic();
        assertFalse(safeList.removeTags(set));
    }

    @Test
    public void addAttributes_addsCorrectlyTest() {
        Set<String> tags = new HashSet<>();
        String[] attributes = {"alt", "src"};
        Safelist safeList = Safelist.basic();
        Attributes result = safeList.addAttributes("img", attributes);
        assertTrue(result.containsAttr("alt"));
        assertTrue(result.containsAttr("src"));
    }

    @Test
    public void removeEnforcedAttribute_removalsCorrectlyTest() {
        Set<String> tags = new HashSet<>();
        String[] attributes = {"alt"};
        Safelist safeList = Safelist.basic();
        Attributes result = safeList.addAttributes("img", attributes);
        assertFalse(safeList.removeEnforcedAttribute("img", "alt"));
    }

    @Test
    public void preserveRelativeLinksPreservesValueTest() {
        boolean preserve = true;
        Safelist safeList = Safelist.relaxed();
        assertTrue(safeList.preserveRelativeLinks(preserve));
    }

    @Test
    public void isSafeTag_returnsTrueForAllowedTagsTest() {
        Set<String> tags = new HashSet<>();
        String[] allowedTags = {"img", "a"};
        for (String tag : allowedTags) {
            assertTrue(Safelist.relaxed().isSafeTag(tag));
        }
    }

    @Test
    public void isSafeAttribute_returnsTrueForAllowedAttributesTest() {
        Set<String> tags = new HashSet<>();
        String[] allowedAttributes = {"alt", "src"};
        Safelist safeList = Safelist.relaxed();
        for (String tag : tags) {
            assertTrue(safeList.isSafeAttribute(tag, null, new Attribute("allowedAttr", "value")));
        }
    }

    @Test
    public void getEnforcedAttributes_returnsEmptySetForNoTagsTest() {
        String tagName = "";
        Safelist safeList = Safelist.relaxed();
        Attributes result = safeList.getEnforcedAttributes(tagName);
        assertTrue(result.isEmpty());
    }

    @Test
    public void getEnforcedAttributes_returnsCorrectAttributesTest() {
        Set<String> tags = new HashSet<>();
        Safelist safeList = Safelist.relaxed();
        String[] attributes = {"alt", "src"};
        Attributes result = safeList.getEnforcedAttributes("img");
        assertTrue(result.containsAttr("alt"));
        assertTrue(result.containsAttr("src"));
    }
}
